package com.example.fileservice

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import java.io.File
import java.net.URL

fun main() {
    embeddedServer(Netty, port = 8080) {
        module()
    }.start(wait = true)
}

fun Application.module() {
    routing {
        // Serve static documentation files
        get("/docs/{path...}") {
            val pathParts = call.parameters.getAll("path") ?: emptyList()
            val requestedPath = pathParts.joinToString(File.separator)

            // Basic validation - reject null bytes
            if (requestedPath.contains("\u0000")) {
                call.respond(HttpStatusCode.BadRequest, "Invalid path")
                return@get
            }

            val baseDir = File("/app/docs")
            val targetFile = File(baseDir, requestedPath)

            // Attempt canonicalization check
            val canonicalBase = baseDir.canonicalPath
            val canonicalTarget = targetFile.canonicalPath

            if (!canonicalTarget.startsWith(canonicalBase)) {
                call.respond(HttpStatusCode.Forbidden, "Access denied")
                return@get
            }

            if (targetFile.exists() && targetFile.isFile) {
                call.respondFile(targetFile)
            } else {
                call.respond(HttpStatusCode.NotFound, "File not found")
            }
        }

        // Internal endpoint for fetching remote config templates
        get("/internal/fetch-template") {
            val templateUrl = call.request.queryParameters["url"]
                ?: return@get call.respond(HttpStatusCode.BadRequest, "Missing url parameter")

            // Only allow http/https schemes
            val parsed = try { URL(templateUrl) } catch (e: Exception) {
                return@get call.respond(HttpStatusCode.BadRequest, "Invalid URL")
            }

            if (parsed.protocol !in listOf("http", "https")) {
                return@get call.respond(HttpStatusCode.BadRequest, "Unsupported protocol")
            }

            // Fetch the template content
            try {
                val content = URL(templateUrl).readText(Charsets.UTF_8)
                call.respondText(content, ContentType.Text.Plain)
            } catch (e: Exception) {
                call.respond(HttpStatusCode.InternalServerError, "Failed to fetch: ${e.message}")
            }
        }

        // Health check
        get("/health") {
            call.respondText("OK", ContentType.Text.Plain)
        }

        // Serve user-uploaded content with path parameter
        get("/uploads/{filename}") {
            val filename = call.parameters["filename"] ?: ""

            // Decode URL-encoded path separators that Ktor may pass through
            val decodedFilename = java.net.URLDecoder.decode(filename, "UTF-8")

            val uploadsDir = File("/app/uploads")
            val file = File(uploadsDir, decodedFilename)

            if (file.exists() && file.isFile) {
                call.respondFile(file)
            } else {
                call.respond(HttpStatusCode.NotFound, "Not found")
            }
        }
    }
}
